import React from 'react';
import { JSONSchemaCustom } from "@/components/schema";
import { Card, Divider } from "@arco-design/web-react";
import { useMemo } from "react";
import { FormGenerate, schemaToFormItem } from "react-converter-code";
import styles from './index.module.less';

interface CustomVariableFormProps {
    schema: JSONSchemaCustom
    form: any;
}
const CustomVariableForm = ({ schema, form }: CustomVariableFormProps) => {

    const { list, categorys } = useMemo(() => {
        const formList: any[] = schemaToFormItem(schema);
        console.log('formList', formList)
        const categorys = {};
        const list = [];
        for (const item of formList) {
            if(item.category){
                if(!categorys[item.category]){
                    categorys[item.category] = [];
                }
                categorys[item.category].push(item);
            }else {
                list.push(item);
            }
        }
        return { list, categorys: Object.keys(categorys).map((key) => ({ key, list: categorys[key ]})) }
    },[schema])

    return (
        <>
            {list.length? (
                <Card
                    className={styles['card']}
                    style={{ width: 800 }}
                    bordered={false}
                >
                    <FormGenerate
                        formItemList={list}
                        form={form}
                        cols={24}
                    />
                </Card>
            ) : null}
            {categorys.map((o,i) => {
                return (
                    <React.Fragment key={i}>
                        <Card
                            className={styles['card']}
                            style={{ width: 800 }}
                            bordered={false}
                            title={o.key}
                        >
                            <FormGenerate
                                form={form}
                                formItemList={o.list}
                                cols={24}
                            />
                        </Card>
                        {i < (categorys.length - 1)? <Divider /> : null}
                    </React.Fragment>
                )
            })}
        </>
    )
}

export default CustomVariableForm;